import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
FILES=sorted((ROOT/'questions/science').glob('question-science-content-ca-iv-1-*.json'),key=lambda p:int(p.stem.rsplit('-',1)[1]))
ITEMS=[
('過濾','要把水和不溶於水的砂子分開，最適合的第一步是？',['過濾','蒸餾','磁選','昇華'],'A','砂子不溶於水且是固體，可用濾紙攔住砂子、讓水通過。'),
('蒸發結晶','從食鹽水取得食鹽晶體，應採用？',['蒸發結晶','過濾未溶解的鹽即可','磁鐵吸引','用篩網分離'],'A','食鹽已溶解，先蒸發水分使食鹽結晶，不能直接過濾溶液。'),
('蒸餾','要從食鹽水取得可飲用的水，最適合使用？',['蒸餾，收集水蒸氣冷凝液','只過濾','磁選','沉澱後倒出所有水'],'A','蒸餾利用水與食鹽揮發性／沸點差異，水蒸氣冷凝後可收集。'),
('磁選','鐵粉和砂子的混合物可用磁鐵分離，利用的是兩者哪項差異？',['磁性','沸點','溶解度','顏色必定不同'],'A','鐵具有磁性，砂子通常沒有，可用磁鐵選出鐵粉。'),
('分離順序','混合物含鐵屑、砂子與食鹽，合理分離順序為？',['先磁選鐵屑，再加水溶解食鹽、過濾砂子，最後蒸發','先蒸發全部，再磁選','先過濾乾燥混合物取出食鹽','只用一次蒸餾分離三者'],'A','先利用磁性取鐵，再利用溶解度與過濾、蒸發依序分離砂與食鹽。'),
('萃取','植物色素溶於有機溶劑而不易溶於水，可利用哪種方法分離？',['萃取','磁選','過濾固體顆粒','直接冷凍'],'A','萃取利用物質在不同溶劑中的溶解度差異，使目標物轉入適合溶劑。'),
('紙層析','紙層析能把墨水中不同色素分開，主要利用各色素？',['在溶劑中的溶解度與對紙的吸附程度不同','質量全部相同','都具有磁性','沸點一定相同'],'A','色素隨溶劑移動速度不同，源自溶解度與吸附程度差異。'),
('結晶純化','若想從含少量雜質的固體混合物取得較純晶體，可利用？',['不同物質溶解度隨溫度變化的差異','所有物質磁性相同','只看顏色','把固體全部燃燒'],'A','重結晶利用溶解度差異，冷卻或蒸發時較純物質形成晶體。'),
('分離依據','選擇分離方法前最重要先比較混合物成分的哪些性質？',['溶解度、磁性、粒徑、沸點等物理性質','名字長短','容器顏色','樣品採集日期'],'A','分離混合物不改變成分，需利用成分間可觀察的物理性質差異。'),
('回收概念','用物理方法分離混合物的共同特色是？',['成分本身沒有變成新物質，仍可被回收','一定發生燃燒','原子被分解','所有成分都消失'],'A','過濾、蒸餾、結晶等是物理分離，成分種類不變，適當條件下可回收。'),
]
for p,(topic,prompt,opts,ans,ex) in zip(FILES,ITEMS):
 d=json.loads(p.read_text()); d['prompt']=prompt; d['options']=[{'id':chr(65+i),'text':t} for i,t in enumerate(opts)]; d['answer']={'value':ans,'explanation':ex}; d['solutionStrategy']=f'先列出混合物成分與各自物理性質，再依溶解度、磁性、粒徑或沸點選擇分離方法；本題聚焦於{topic}。'; d['solutionSteps']=['先辨認混合物中的各成分及其狀態、溶解度、磁性或沸點。','選擇不改變物質種類的物理分離方法，若有多種成分則安排合理順序。',f'依分離原理逐項比對，得到答案{ans}。',f'回看解析：{ex}','最後確認分離方法不是化學反應，並檢查目標成分最後是否能被回收。']; d['reviewStatus']='draft'; d['updatedAt']='2026-09-08'; d['provenance']['authoringNote']='依官方課綱與公開會考、公立國中試題所呈現的混合物分離、物性差異、過濾、結晶、蒸餾、磁選、萃取與層析方向獨立改寫；未複製原題文字、選項、圖表或答案；待第二輪 AI／Terra 內容複核。'; p.write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
